int gcd(int a, int b) {
    int t;

    while (b != 0) {
        t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    printf("%d %d\n", gcd(48, 18), gcd(17, 5));
    return 0;
}

