#include <stdio.h>

#define MAXN 100

/* 返回数组 a 中严格大于平均值的元素个数，平均值按实数计算 */
int CountAboveAverage(const int a[], int n) {
    int i, count = 0;
    double sum = 0.0, avg;

    for (i = 0; i < n; i++)
        sum += a[i];
    avg = sum / n;
    for (i = 0; i < n; i++)
        if (a[i] > avg)
            count++;
    return count;
}

int main(void) {
    int a[MAXN], n, i;

    if (scanf("%d", &n) != 1)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    printf("%d\n", CountAboveAverage(a, n));
    return 0;
}

