#include <stdio.h>

/* 计算 (a^b) mod p，要求 b >= 0，时间复杂度 O(log b) */
long long FastPower(long long a, long long b, long long p) {
    long long result = 1;

    a = a % p;
    while (b > 0) {
        if (b % 2 == 1)
            result = result * a % p;
        b = b / 2;
        a = a * a % p;
    }
    return result;
}

int main(void) {
    long long a, b, p;

    while (scanf("%lld %lld %lld", &a, &b, &p) == 3)
        printf("%lld\n", FastPower(a, b, p));
    return 0;
}

